package studio.muzi.fongmi;
import android.app.Activity;import android.content.*;import android.os.Bundle;import android.speech.RecognizerIntent;import android.view.*;import android.view.inputmethod.*;import android.widget.*;import java.util.*;
/** Standard speech activity with the TV's voice-capable input method as OEM fallback. */
public final class VoiceSearch {
 public static final int REQUEST=7914;
 static EditText find(View view){if(view instanceof EditText)return (EditText)view;if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int i=0;i<g.getChildCount();i++){EditText e=find(g.getChildAt(i));if(e!=null)return e;}}return null;}
 static EditText field(Activity a){int id=a.getResources().getIdentifier("keyword","id",a.getPackageName());View v=id==0?null:a.findViewById(id);return v instanceof EditText?(EditText)v:find(a.findViewById(android.R.id.content));}
 static void keyboard(Activity a){keyboard(a,false);}
 static void keyboard(Activity a,boolean explicit){EditText e=field(a);if(e==null)return;e.setShowSoftInputOnFocus(true);e.requestFocus();e.postDelayed(()->{if(!a.isFinishing()){InputMethodManager input=(InputMethodManager)a.getSystemService(Context.INPUT_METHOD_SERVICE);if(explicit)input.restartInput(e);input.showSoftInput(e,explicit?InputMethodManager.SHOW_FORCED:InputMethodManager.SHOW_IMPLICIT);}},180);}
 public static void install(Activity a){EditText e=field(a);if(e==null)return;e.setShowSoftInputOnFocus(true);e.setImeOptions(EditorInfo.IME_ACTION_SEARCH|EditorInfo.IME_FLAG_NO_EXTRACT_UI);e.setHint("说出或输入片名");e.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_SEARCH||action==EditorInfo.IME_ACTION_DONE||(event!=null&&event.getKeyCode()==KeyEvent.KEYCODE_ENTER&&event.getAction()==KeyEvent.ACTION_UP)){submit(a,e.getText().toString());return true;}return false;});int id=a.getResources().getIdentifier("mic","id",a.getPackageName());View mic=id==0?null:a.findViewById(id);if(mic!=null){mic.setContentDescription("语音搜索");mic.setOnClickListener(v->start(a));}keyboard(a);}
 public static Intent intent(){return new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_LANGUAGE,"zh-CN").putExtra(RecognizerIntent.EXTRA_PROMPT,"请说出片名").putExtra(RecognizerIntent.EXTRA_MAX_RESULTS,1);}
 static final java.util.WeakHashMap<Activity,Long> starts=new java.util.WeakHashMap<Activity,Long>();
 public static void start(Activity a){long now=android.os.SystemClock.uptimeMillis();Long prior=starts.get(a);if(prior!=null&&now-prior<800)return;starts.put(a,now);Intent i=intent();if(i.resolveActivity(a.getPackageManager())!=null){try{a.startActivityForResult(i,REQUEST);return;}catch(ActivityNotFoundException ignored){}}keyboard(a,true);Toast.makeText(a,"输入框已就绪，请长按遥控器麦克风说片名",Toast.LENGTH_LONG).show();}
 public static boolean voiceKey(int code){return code==KeyEvent.KEYCODE_VOICE_ASSIST||code==KeyEvent.KEYCODE_ASSIST||code==KeyEvent.KEYCODE_SEARCH;}
 public static boolean key(Activity a,KeyEvent e){if(!voiceKey(e.getKeyCode()))return false;if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0)start(a);return true;}
 static void submit(Activity a,String text){if(text==null||text.trim().isEmpty())return;EditText e=field(a);if(e==null)return;String value=text.trim();e.setText(value);e.setSelection(e.length());try{a.getClass().getMethod("I").invoke(a);}catch(Exception error){android.util.Log.w("muzi-voice","search dispatch unavailable",error);}}
 public static boolean result(Activity a,int request,int code,Intent data){if(request!=REQUEST)return false;if(code==Activity.RESULT_OK&&data!=null){ArrayList<String> text=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(text!=null&&!text.isEmpty())submit(a,text.get(0));}return true;}
}
